RSpec.describe Invoices::LegacyReservations, committed_data: true do
  let(:redelivery_company) { create(:company) }
  let(:redelivery_client) { create(:client, company: redelivery_company) }
  let(:redelivery_project) { create(:project, client: redelivery_client, billable: true) }
  let(:redelivery_user) { create(:user, current_workspace_id: redelivery_company.id) }

  def redelivery_spec_entry
    create(:timesheet_entry, user: redelivery_user, project: redelivery_project, bill_status: "unbilled")
  end

  # "Commit applies the removals and is idempotent by operation_id; abort after a rollback finds nothing to undo."
  it "a redelivered draft-removal commit changes nothing and never unlocks an entry a successor invoice took since" do
    draft = create(:invoice, company: redelivery_company, client: redelivery_client)
    kept_line = create(:invoice_line_item, invoice: draft, timesheet_entry: redelivery_spec_entry, rate: 100, quantity: 60)
    removed_line = create(:invoice_line_item, invoice: draft, timesheet_entry: redelivery_spec_entry, rate: 100, quantity: 60)
    removed_entry = removed_line.timesheet_entry

    InvoiceLineItem.find(removed_line.id).destroy!

    expect(removed_entry.reload.locked).to be(false)
    commit_row = InvoiceOperationOutboxItem
      .where(company_id: redelivery_company.id, invoice_id: draft.id, kind: "commit").order(:id).last
    expect(commit_row.delivered_at).to be_present

    successor = create(:invoice, company: redelivery_company, client: redelivery_client)
    create(:invoice_line_item, invoice: successor, timesheet_entry: removed_entry, rate: 100, quantity: 60)
    expect(removed_entry.reload.locked).to be(true)
    holdings_before = InvoiceEntryHolding.where(company_id: redelivery_company.id).order(:invoice_id)
      .pluck(:invoice_id, :entry_ids, :disposition)

    commit_row.update_columns(delivered_at: nil)
    DeliverInvoiceOperationJob.perform_now(commit_row.id)

    expect(removed_entry.reload.locked).to be(true)
    expect(kept_line.timesheet_entry.reload.locked).to be(true)
    expect(InvoiceEntryHolding.where(company_id: redelivery_company.id).order(:invoice_id)
      .pluck(:invoice_id, :entry_ids, :disposition)).to eq(holdings_before)
    expect(InvoiceEntryHolding.find_by!(company_id: redelivery_company.id, invoice_id: successor.id).entry_ids)
      .to eq([removed_entry.id])
  end
end

