  # "Prepare locks new entries in the invoice transaction, so a rollback undoes them. Commit applies the removals
  # and is idempotent by operation_id; abort after a rollback finds nothing to undo."
  it "a save refused after an earlier invoice prepared leaves that invoice's new entry unlocked with one failed intent and one abort row" do
    holder = create(:invoice, company: rollback_company, client: rollback_client)
    held_entry = rollback_spec_entry
    create(:invoice_line_item, invoice: holder, timesheet_entry: held_entry, rate: 100, quantity: 60)
    expect(held_entry.reload.locked).to be(true)
    holder_holding = InvoiceEntryHolding.find_by!(company_id: rollback_company.id, invoice_id: holder.id)
