      .attributes.slice("entry_ids", "disposition")).to eq(holder_holding)

    first_intents = InvoiceOperationIntent.where(company_id: rollback_company.id, invoice_id: first_invoice_id)
    expect(first_intents.pluck(:state)).to eq(["failed"])
    expect(InvoiceOperationOutboxItem.where(company_id: rollback_company.id, invoice_id: first_invoice_id).pluck(:kind))
      .to eq(["abort"])
