RSpec.describe Invoices::LegacyReservations do
  # "An id from another company gives not_found." The not-in-company answer must never reveal
  # that, or where, the other company's entry is reserved, so the reason is never on_another_invoice.
  # Scenario: a forged entry id from another company that is held active there.
  it "answers not_found and leaves the row untouched for another company's entry held by that company's kept invoice" do
    own_company = create(:company)
    own_invoice = create(:invoice, company: own_company, client: create(:client, company: own_company))
    other_company = create(:company)
    other_client = create(:client, company: other_company)
    other_user = create(:user, current_workspace_id: other_company.id)
    other_project = create(:project, client: other_client, billable: true)
    foreign_entry = create(:timesheet_entry, user: other_user, project: other_project, bill_status: "unbilled")
    other_draft = create(:invoice, company: other_company, client: other_client)
    create(:invoice_line_item, invoice: other_draft, timesheet_entry: foreign_entry, rate: 100, quantity: 60)
    expect(foreign_entry.reload.locked).to be(true)
    row_before = foreign_entry.reload.attributes

    request = Invoices::ReservationRequest.new(
      company_id: own_company.id, invoice_id: own_invoice.id, operation_id: SecureRandom.uuid,
      generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [foreign_entry.id]
    )
    outcome = ApplicationRecord.transaction { described_class.new.prepare(request) }

    expect(outcome.state).to eq("refused")
    expect(outcome.conflicts.map { |conflict| conflict[:reason].to_s }).to eq(["not_found"])
    expect(foreign_entry.reload.attributes).to eq(row_before)
    expect(InvoiceEntryHolding.where(company_id: own_company.id)).to be_empty
  end
end

RSpec.describe Invoices::LegacyReservations, committed_data: true do
  # "Commit applies the removals and is idempotent by operation_id; abort after a rollback finds nothing to undo."
  # Scenario: the worker or the recovery sweep delivers an old release commit again, after the
  # draft took the entry back. Replaying the removal must not free an entry the draft holds again.
  it "leaves an entry locked when a stale release commit is delivered again after a newer operation re-added it" do
    company = create(:company)
    client = create(:client, company:)
    owner = create(:user, current_workspace_id: company.id)
    project = create(:project, client:, billable: true)
    entry = create(:timesheet_entry, user: owner, project:, bill_status: "unbilled")
    draft = create(:invoice, company:, client:)

    first_line = create(:invoice_line_item, invoice: draft, timesheet_entry: entry, rate: 100, quantity: 60)
    expect(entry.reload.locked).to be(true)
    InvoiceLineItem.find(first_line.id).destroy!
    expect(entry.reload.locked).to be(false)
    release_intent = InvoiceOperationIntent.where(company_id: company.id, invoice_id: draft.id, state: "committed")
      .find { |intent| intent.desired_entry_ids.empty? }
    expect(release_intent).to be_present

    create(:invoice_line_item, invoice: draft, timesheet_entry: entry, rate: 100, quantity: 60)
    expect(entry.reload.locked).to be(true)

    stale_request = Invoices::ReservationRequest.new(
      company_id: company.id, invoice_id: draft.id, operation_id: release_intent.operation_id,
      generation: release_intent.generation, disposition: release_intent.disposition,
      entries: release_intent.desired_entry_ids
    )
    outcomes = Array.new(2) { described_class.new.commit(stale_request) }

    expect(outcomes.map(&:state)).to eq(%w[committed committed])
    expect(entry.reload.locked).to be(true)
    expect(InvoiceEntryHolding.find_by(company_id: company.id, invoice_id: draft.id).entry_ids).to eq([entry.id])
  end
end

# frozen_string_literal: true
require "rails_helper"

RSpec.describe Invoices::LegacyReservations, committed_data: true do
  let(:race_company) { create(:company) }
  let(:race_client) { create(:client, company: race_company) }
  let(:race_project) { create(:project, client: race_client, billable: true) }
  let(:race_user) { create(:user, current_workspace_id: race_company.id) }

  def race_request(invoice, entry)
    Invoices::ReservationRequest.new(
      company_id: race_company.id, invoice_id: invoice.id, operation_id: SecureRandom.uuid,
      generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [entry.id]
    )
  end

  # "a second kept invoice on the same entry fails with \"entry is on another invoice\""
  # Two saves of one entry run at the same time: the second prepare must wait on
  # the entry row lock, then read the first invoice's committed claim and be
  # refused, never both succeed and never end in a deadlock error.
  it "refuses the second of two concurrent prepares of one entry as on_another_invoice once the first commits" do
    entry = create(:timesheet_entry, user: race_user, project: race_project, bill_status: "unbilled")
    first_invoice = create(:invoice, company: race_company, client: race_client)
    second_invoice = create(:invoice, company: race_company, client: race_client)
    first_request = race_request(first_invoice, entry)
    second_request = race_request(second_invoice, entry)

    first_prepared = Queue.new
    release_first = Queue.new
    second_pid = Queue.new

    first = Thread.new do
      ActiveRecord::Base.connection_pool.with_connection do
        ActiveRecord::Base.transaction do
          outcome = described_class.new.prepare(first_request)
          # What the coordinator's settle writes in the same invoice transaction.
          InvoiceEntryHolding.upsert(
            { company_id: race_company.id, invoice_id: first_invoice.id, entry_ids: [entry.id], disposition: "active" },
            unique_by: %i[company_id invoice_id]
          )
          first_prepared << true
          release_first.pop
          outcome
        end
      end
    end

    first_prepared.pop
    second = Thread.new do
      ActiveRecord::Base.connection_pool.with_connection do |connection|
        second_pid << connection.raw_connection.backend_pid
        ActiveRecord::Base.transaction { described_class.new.prepare(second_request) }
      end
    end

    pid = second_pid.pop
    waited = 50.times.any? do
      blocked = ActiveRecord::Base.connection.select_value("SELECT cardinality(pg_blocking_pids(#{pid}))").to_i.positive?
      blocked || (sleep(0.1) && false)
    end
    release_first << true

    first_outcome = first.value
    second_outcome = second.value

    expect(waited).to be(true)
    expect(first_outcome.state).to eq("prepared")
    expect(second_outcome.state).to eq("refused")
    expect(second_outcome.conflicts).to include(a_hash_including(entry_id: entry.id, reason: "on_another_invoice"))
    expect(entry.reload.locked).to be(true)
    expect(InvoiceEntryHolding.where(company_id: race_company.id, invoice_id: second_invoice.id)).to be_empty
  end
end

RSpec.describe Invoices::LegacyReservations do
  let(:adapter_unit_company) { create(:company) }
  let(:adapter_unit_client) { create(:client, company: adapter_unit_company) }
  let(:adapter_unit_project) { create(:project, client: adapter_unit_client, billable: true) }
  let(:adapter_unit_user) { create(:user, current_workspace_id: adapter_unit_company.id) }

  def adapter_unit_entry(locked:)
    entry = create(:timesheet_entry, user: adapter_unit_user, project: adapter_unit_project, bill_status: "unbilled")
    entry.update_columns(locked:)
    entry
  end

  def adapter_unit_request(invoice_id, entries, disposition: "active", operation_id: SecureRandom.uuid)
    Invoices::ReservationRequest.new(
      company_id: adapter_unit_company.id, invoice_id:, operation_id:,
      generation: TimekeepingOwnership.current.generation, disposition:, entries:
    )
  end

  def adapter_unit_hold(invoice_id, entries, disposition: "active")
    InvoiceEntryHolding.create!(company_id: adapter_unit_company.id, invoice_id:, entry_ids: entries.map(&:id), disposition:)
  end

  it "applies a removal once when the same commit is delivered twice" do
    removed = adapter_unit_entry(locked: true)
    kept = adapter_unit_entry(locked: true)
    adapter_unit_hold(700_001, [removed, kept])
    request = adapter_unit_request(700_001, [kept.id])

    expect(described_class.new.prepare(request).state).to eq("prepared")
    InvoiceEntryHolding.where(company_id: adapter_unit_company.id, invoice_id: 700_001).update_all(entry_ids: [kept.id])
    expect(removed.reload.locked).to be(true)

    first = described_class.new.commit(request)
    after_first = [removed.reload.locked, kept.reload.locked, LegacyEntryRelease.sole.attributes]
    second = described_class.new.commit(request)

    expect([first.state, second.state]).to eq(%w[committed committed])
    expect(after_first.first(2)).to eq([false, true])
    expect(after_first.last["applied_at"]).to be_present
    expect([removed.reload.locked, kept.reload.locked, LegacyEntryRelease.sole.attributes]).to eq(after_first)
  end

  it "admits an unclaimed entry without writing a lock, a holding or a release" do
    entry = adapter_unit_entry(locked: false)

    outcome = described_class.new.admit(adapter_unit_request(700_002, [entry.id]))

    expect(outcome.state).to eq("prepared")
    expect(entry.reload.locked).to be(false)
    expect(InvoiceEntryHolding.where(company_id: adapter_unit_company.id)).to be_empty
    expect(LegacyEntryRelease.where(company_id: adapter_unit_company.id)).to be_empty
  end

  it "leaves an unlocked entry unlocked for a retained request" do
    entry = adapter_unit_entry(locked: false)

    outcome = described_class.new.prepare(adapter_unit_request(700_003, [entry.id], disposition: "retained"))

    expect(outcome.state).to eq("prepared")
    expect(entry.reload.locked).to be(false)
  end

  it "drops a discarded invoice's retained claim when a successor takes the entry, and a rollback restores it" do
    entry = adapter_unit_entry(locked: true)
    retired = create(:invoice, company: adapter_unit_company, client: adapter_unit_client, status: :sent)
    retired.update_columns(discarded_at: Time.current)
    adapter_unit_hold(retired.id, [entry], disposition: "retained")
    request = adapter_unit_request(700_004, [entry.id])

    ApplicationRecord.transaction(requires_new: true) do
      expect(described_class.new.prepare(request).state).to eq("prepared")
      expect(InvoiceEntryHolding.find_by!(company_id: adapter_unit_company.id, invoice_id: retired.id).entry_ids).to eq([])
      raise ActiveRecord::Rollback
    end

    expect(InvoiceEntryHolding.find_by!(company_id: adapter_unit_company.id, invoice_id: retired.id).entry_ids).to eq([entry.id])
    expect(described_class.new.prepare(request).state).to eq("prepared")
    expect(InvoiceEntryHolding.find_by!(company_id: adapter_unit_company.id, invoice_id: retired.id).entry_ids).to eq([])
    expect(entry.reload.locked).to be(true)
  end

  it "aborts without changing any lock after a rolled-back prepare" do
    entry = adapter_unit_entry(locked: false)
    request = adapter_unit_request(700_005, [entry.id])
    ApplicationRecord.transaction(requires_new: true) do
      described_class.new.prepare(request)
      raise ActiveRecord::Rollback
    end

    expect(described_class.new.abort(request).state).to eq("aborted")
    expect(entry.reload.locked).to be(false)
    expect(LegacyEntryRelease.where(company_id: adapter_unit_company.id)).to be_empty
  end
end
